import httpx

def test_fetch_latest_tag_uses_stub_transport():
    def handler(request):
        assert request.url.path == "/repos/acme/tool/releases/latest"
        return httpx.Response(200, json={"tag_name": "v1.4.0"})
    client = httpx.Client(transport=httpx.MockTransport(handler), base_url="https://api.github.com")
    assert fetch_latest_tag(client, "acme/tool") == "v1.4.0"

import json
import subprocess
import sys

def run_lint_adapter(path):
    proc = subprocess.run([sys.executable, "-m", "fixture_lint", "--json", str(path)], capture_output=True, text=True)
    try:
        return json.loads(proc.stdout)["results"]
    except (json.JSONDecodeError, KeyError):
        return []

def test_clean_file_has_no_results(tmp_path):
    (tmp_path / "ok.py").write_text("x = 1\n")
    assert run_lint_adapter(tmp_path / "ok.py") == []

#!/usr/bin/env bash
set -euo pipefail
root=$(mktemp -d)
trap 'rm -rf "$root"' EXIT
printf 'b\na\nb\n' > "$root/in.txt"
out=$(python3 tools/dedupe_sort.py "$root/in.txt")
case "$out" in
  *a*) echo ok ;;
  *) exit 1 ;;
esac
